for i,p in enumerate(P):
 nav='<header class="'+('admin-header' if p['group']=='Staff' else 'app-header')+'"><a class="wordmark" href="index.html">Swoovr</a><nav class="tab-bar">'+''.join(f'<a class="tab" href="{s}.html">{t}</a>' for s,t in ([('admin','Moderation'),('queue','Queue'),('appeals','Appeals'),('media-review','Photos'),('accounts','Accounts'),('safety-resources','Safety')] if p['group']=='Staff' else [('explore','Explore'),('connections','Connections'),('chats','Chats'),('account','Me')]))+'</nav></header>'
 meta=f'<aside class="gallery-meta"><div class="gallery-controls"><a href="index.html">All {len(P)} screens</a><a href="{P[(i-1)%len(P)]["slug"]}.html">Previous</a><a href="{P[(i+1)%len(P)]["slug"]}.html">Next</a><label>Preview <select id="gallery-mode"><option>System</option><option>Light</option><option>Dark</option></select></label></div><p>{p["note"]}</p><p>Source: <code>{p["source"]}</code></p><div class="gallery-status" role="status" aria-live="polite">Offline gallery · fictional adults · controls are illustrative</div></aside>'
 (OUT/(p['slug']+'.html')).write_text(document(p['title'],meta+nav+'<main class="'+('admin-main' if p['group']=='Staff' else '')+'">'+p['body']+'</main>',p['group']=='Staff'))
index=f'<main><p class="eyebrow">Main branch review / 27 October 2026 · AB–AI screens added 28 October 2026</p><h1>Swoovr, screen by screen.</h1><p>{len(P)} offline HTML snapshots of the public, member and staff interfaces. Open any screen, resize the browser, and switch light/dark. These are source-based reconstructions, not screenshots of authenticated sessions.</p><p><strong>CONFIRMED:</strong> Standard black and white is the default; eight schemes are personal choices. <strong>DEFAULT:</strong> fictional populated examples and static controls. <strong>OPEN:</strong> runtime and native-device visual parity.</p><p>Base main commit: <code>{sha}</code>. CSS copied unchanged from that commit. Auth screens approximate the hosted Keycloak layout; native MAUI screens are not rendered here. Planned commerce, venue and voucher screens are excluded; photo screens use synthetic placeholders.</p>'
for group in ['Public','Member','Staff']:
 index+=f'<h2 class="section-heading">{group}</h2><div class="gallery-index">'+''.join(f'<a href="{p["slug"]}.html"><span class="eyebrow">{group}</span><h2>{p["title"]}</h2><span>View screen →</span></a>' for p in P if p['group']==group)+'</div>'
index+='</main>'
(OUT/'index.html').write_text(document('Screen index',index))
(OUT/'manifest.json').write_text(json.dumps({'base_commit':sha,'screens':[{k:v for k,v in p.items() if k!='body'} for p in P]},indent=2))
print(f'Built {len(P)} screens at {OUT}')
